  ('be710663-7421-5308-b58a-12d46f5e620b', null, (select id from public.skills where slug = 'write-g10-writing-with-evidence'), null, 'easy',
   $q$Which sentence should replace sentence 2 to state a claim that the rest of the draft supports?$q$, $q$[{"text":"Rowing is one of the hardest sports in high school, so more students should try it.","is_correct":false,"misconception_token":"opinion-not-analysis"},{"text":"Delgado shows Mei growing from a rower who trusts only her own strength into one who values moving in time with her team.","is_correct":true},{"text":"Mei is the strongest and most talented athlete on her team throughout the whole story.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Delgado's story is about a girl named Mei who joins a rowing team at her high school.","is_correct":false,"misconception_token":"topic-not-claim"}]$q$::jsonb, $q$Delgado shows Mei growing from a rower who trusts only her own strength into one who values moving in time with her team.$q$, $q$The draft traces Mei's change from forcing strokes to matching her crew, so a claim about that growth fits. The choice that Mei is the most talented athlete is not supported, since the coach says her power is "fighting the boat."$q$, 'draft', '208778e9-eda2-5ea7-bd39-41e7bfa0a4e1')
