  ('0faa0b9c-b349-500a-a5ac-fd85a177b8c1', null, (select id from public.skills where slug = 'write-g11-narrative-writing'), null, 'hard',
   $q$Which sentence is the turning point that moves the narrative from the problem toward its resolution?$q$, $q$[{"text":"sentence 15, when Mr. Pell says the shovel is free","is_correct":false,"misconception_token":"confuses-resolution-with-turn"},{"text":"sentence 17, when Emeka returns to the store in April","is_correct":false,"misconception_token":"confuses-epilogue-with-turn"},{"text":"sentence 12, when the narrator remembers the damaged shovel in the back room","is_correct":true},{"text":"sentence 7, when Emeka enters the store and asks about shovels","is_correct":false,"misconception_token":"confuses-problem-with-turn"}]$q$::jsonb, $q$sentence 12, when the narrator remembers the damaged shovel in the back room$q$, $q$Sentence 12 is where the narrator first sees a way to help, shifting the story from "no shovels" toward a solution. Sentence 7 introduces the problem rather than turning it.$q$, 'draft', '0263af8c-9911-59cf-b483-df6aaced16f9')
