  ('bae35d10-c080-533c-81b0-1d547cbd4544', null, (select id from public.skills where slug = 'write-g11-narrative-writing'), null, 'medium',
   $q$Why is sentence 7 important to the narrative as a whole?$q$, $q$[{"text":"It starts a second thread, a reluctant Kofi, that the ending resolves when he looks through the eyepiece.","is_correct":true},{"text":"It explains why the club chose Harmon Hill as its viewing spot.","is_correct":false,"misconception_token":"misreads-purpose"},{"text":"It provides the reason that half the club decided to leave at ten-thirty.","is_correct":false,"misconception_token":"false-cause-effect"},{"text":"It shows that the club members were careless about watching younger guests.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$It starts a second thread, a reluctant Kofi, that the ending resolves when he looks through the eyepiece.$q$, $q$Kofi begins uninterested and asleep, and in sentence 16 he stares through the eyepiece in silence, so his thread pays off in the ending. Nothing links his nap to the others leaving.$q$, 'draft', '889c5e8c-d2ae-54ab-bcb8-2938fb757d75')
