  ('edf3abb2-60d4-56c4-b346-9fdec5cdb276', null, (select id from public.skills where slug = 'write-g11-precise-language'), null, 'easy',
   $q$Read the sentence: "The museum's conservator restored the faded tapestry back to its original condition." Which revision removes the redundancy?$q$, $q$[{"text":"The museum's conservator restored the faded tapestry back again to its original condition.","is_correct":false,"misconception_token":"redundancy-added"},{"text":"The museum's conservator restored the faded tapestry back to its first, original condition.","is_correct":false,"misconception_token":"redundancy-remains"},{"text":"The museum's conservator fixed up the faded tapestry back to how it was.","is_correct":false,"misconception_token":"informal-and-redundant"},{"text":"The museum's conservator restored the faded tapestry to its original condition.","is_correct":true}]$q$::jsonb, $q$The museum's conservator restored the faded tapestry to its original condition.$q$, $q$"Restored" already means brought back, so "back" is unnecessary. The other choices keep "back" or add more repetition, and "fixed up" is too casual.$q$, 'draft', null)
