  ('4c16bad1-4bc8-5a3e-b671-c1a6d830af5c', null, (select id from public.skills where slug = 'write-g11-precise-language'), null, 'medium',
   $q$Read the sentences: "Lucia Ferrante restored the clock tower. She is a retired engineer. The tower had been silent for decades." Which revision combines them most effectively?$q$, $q$[{"text":"Lucia Ferrante is a retired engineer and she restored the clock tower and it had been silent for decades.","is_correct":false,"misconception_token":"stringy-and"},{"text":"Lucia Ferrante restored the clock tower, she is a retired engineer, the tower had been silent for decades.","is_correct":false,"misconception_token":"comma-splice"},{"text":"Lucia Ferrante, a retired engineer, restored the clock tower, which had been silent for decades.","is_correct":true},{"text":"A retired engineer, the clock tower had been silent for decades until Lucia Ferrante restored it.","is_correct":false,"misconception_token":"dangling-modifier"}]$q$::jsonb, $q$Lucia Ferrante, a retired engineer, restored the clock tower, which had been silent for decades.$q$, $q$An appositive ("a retired engineer") and a relative clause tuck the extra details into one clear sentence. The version opening "A retired engineer, the clock tower" is compact, but it makes the clock tower the retired engineer.$q$, 'draft', null)
