  ('4eff455b-789c-5944-9706-766a77b541d1', null, (select id from public.skills where slug = 'write-g11-precise-language'), null, 'medium',
   $q$A formal essay on the history of biology includes the sentence: "Folks back then didn't have a clue how fungi spread." Which revision keeps the essay's formal style?$q$, $q$[{"text":"Folks at the time did not understand how fungi spread.","is_correct":false,"misconception_token":"informal-word"},{"text":"People at the time didn't have a clue how fungi spread.","is_correct":false,"misconception_token":"informal-idiom"},{"text":"People back then were totally clueless about how fungi spread.","is_correct":false,"misconception_token":"slang"},{"text":"People at the time did not understand how fungi spread.","is_correct":true}]$q$::jsonb, $q$People at the time did not understand how fungi spread.$q$, $q$The correct choice replaces "folks," "back then," and "didn't have a clue" with formal wording. "Folks at the time did not understand" fixes the idiom but keeps the casual "folks."$q$, 'draft', null)
