  ('89531778-a21b-5e98-8b7d-9b56eb0c6098', null, (select id from public.skills where slug = 'write-g11-precise-language'), null, 'medium',
   $q$A lab report says: "We stuck the beakers in the fridge for a bit." Which revision best fits the formal style of a lab report?$q$, $q$[{"text":"The beakers were placed in the fridge for a bit.","is_correct":false,"misconception_token":"informal-word"},{"text":"The beakers were placed in the refrigerator briefly.","is_correct":true},{"text":"We stuck the beakers in the refrigerator for a while.","is_correct":false,"misconception_token":"informal-word"},{"text":"The beakers were frozen overnight.","is_correct":false,"misconception_token":"changes-meaning"}]$q$::jsonb, $q$The beakers were placed in the refrigerator briefly.$q$, $q$"Placed," "refrigerator," and "briefly" replace the casual "stuck," "fridge," and "for a bit." "The beakers were placed in the fridge for a bit" improves the verb but keeps "fridge" and "for a bit."$q$, 'draft', null)
