  ('37d41b05-a53b-52bf-aa32-1c22f46fa415', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Read the sentence: "When a hiker reaches the summit, you can see three states on a clear day." Which revision fixes the shift in person?$q$, $q$[{"text":"When a hiker reaches the summit, you could see three states on a clear day.","is_correct":false,"misconception_token":"person-shift-unfixed"},{"text":"When you reach the summit, a hiker can see three states on a clear day.","is_correct":false,"misconception_token":"person-shift-reversed"},{"text":"When hikers reach the summit, they can see three states on a clear day.","is_correct":true},{"text":"When a hiker reaches the summit, one could have seen three states on a clear day.","is_correct":false,"misconception_token":"person-and-tense-shift"}]$q$::jsonb, $q$When hikers reach the summit, they can see three states on a clear day.$q$, $q$"Hikers" and "they" are both third person, so the sentence no longer shifts from a hiker to "you." Reversing the order to "you" and then "a hiker" keeps the same shift in person.$q$, 'draft', null)
