  ('d7c1ad77-8a1b-5bea-a61c-9eb85babce27', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Read the sentence: "The wind farm generates power for nearly nine thousand homes, however, some residents worry about noise from the turbines." Which revision of "homes, however, some" is correct?$q$, $q$[{"text":"homes, however some","is_correct":false,"misconception_token":"conjunctive-adverb-with-comma-only"},{"text":"homes, however; some","is_correct":false,"misconception_token":"misplaced-semicolon"},{"text":"homes however, some","is_correct":false,"misconception_token":"fused-sentence"},{"text":"homes. However, some","is_correct":true}]$q$::jsonb, $q$homes. However, some$q$, $q$"However" is a conjunctive adverb, so the clauses must be separated by a period (or a semicolon) before it, with a comma after it. Putting the semicolon after "however" attaches it to the wrong clause and leaves a comma splice before it.$q$, 'draft', null)
