  ('4fc6a56d-9c55-5d87-bc38-cd28498195f4', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Which sentence is punctuated correctly?$q$, $q$[{"text":"The museum's glassblowers work in front of visitors and, each piece takes about an hour.","is_correct":false,"misconception_token":"misplaced-comma-with-conjunction"},{"text":"The museum's glassblowers work in front of visitors, and each piece takes about an hour.","is_correct":true},{"text":"The museum's glassblowers work in front of visitors, each piece takes about an hour.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"The museum's glassblowers work in front of visitors each piece takes about an hour.","is_correct":false,"misconception_token":"fused-sentence"}]$q$::jsonb, $q$The museum's glassblowers work in front of visitors, and each piece takes about an hour.$q$, $q$Two independent clauses can be joined by a comma followed by a coordinating conjunction such as "and." The comma belongs before "and," not after it, so "visitors and, each" is incorrect.$q$, 'draft', null)
