  ('ee99f514-9fbd-5f9e-ae30-17214dc11452', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'hard',
   $q$Read the sentence: "The volunteers sorted the donated books by genre, and then the shelves were labeled by them." Which revision removes the needless shift from active to passive voice?$q$, $q$[{"text":"The volunteers sorted the donated books by genre, and then the shelves were labeled.","is_correct":false,"misconception_token":"voice-shift-unfixed"},{"text":"The volunteers sorted the donated books by genre and then labeled the shelves.","is_correct":true},{"text":"The donated books were sorted by genre, and then the volunteers labeled the shelves.","is_correct":false,"misconception_token":"voice-shift-reversed"},{"text":"The volunteers sorted the donated books by genre, then they labeled the shelves.","is_correct":false,"misconception_token":"comma-splice-created"}]$q$::jsonb, $q$The volunteers sorted the donated books by genre and then labeled the shelves.$q$, $q$Giving "volunteers" two active verbs, "sorted" and "labeled," removes the shift. The "then they labeled" version is active throughout but joins two independent clauses with only a comma.$q$, 'draft', null)
