  ('6849d8b4-5415-5027-bb0a-4491db482d7e', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'hard',
   $q$Which choice contains no sentence boundary or punctuation error?$q$, $q$[{"text":"When the power failed during the storm, the aquarium's generators started automatically so, no tank lost its filtration.","is_correct":false,"misconception_token":"misplaced-comma-with-conjunction"},{"text":"When the power failed during the storm, the aquarium's generators started automatically, no tank lost its filtration.","is_correct":false,"misconception_token":"comma-splice-created"},{"text":"When the power failed during the storm. The aquarium's generators started automatically, so no tank lost its filtration.","is_correct":false,"misconception_token":"subordinate-clause-fragment"},{"text":"When the power failed during the storm, the aquarium's generators started automatically, so no tank lost its filtration.","is_correct":true}]$q$::jsonb, $q$When the power failed during the storm, the aquarium's generators started automatically, so no tank lost its filtration.$q$, $q$The dependent "When" clause attaches with a comma, and a comma before "so" joins the two independent clauses correctly. Without "so," the last two clauses form a comma splice.$q$, 'draft', null)
